/**
 * Published explainer videos per wizard (`videoKey` of lib/wizards/registry).
 * GENERATED by `node scripts/wizard-videos.mjs` from motion-studio's
 * out/Orithon-Guide.publish.json after `publish.mjs` uploaded the renders to
 * Bunny CDN — do not edit by hand. An empty map simply hides the «Δείτε το
 * video» button and the help player until the video is published.
 */
import type { WizardVideo } from "@/components/wizards/HelpVideoPlayer";
import { getWizard, type WizardKey } from "./registry";

export const WIZARD_VIDEOS: Record<string, WizardVideo> = {};

export function videoForWizard(key: WizardKey): WizardVideo | null {
  return WIZARD_VIDEOS[getWizard(key).videoKey] ?? null;
}
